import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { loginUser } from '../services/api'; // Adjust the path as needed
import { Box, TextField, Button, Typography, Grid, Card, CardContent } from '@mui/material';

const Login = () => {
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');
    const [errorMessage, setErrorMessage] = useState('');
    const navigate = useNavigate();

    const handleSubmit = async (e) => {
        e.preventDefault();
        try {
            const response = await loginUser({ username, password });
            console.log("Login API Response:", response);
    
            if (response && response.user && response.user.role) {
                const role = response.user.role;
                console.log("User role:", role);
                // Perform actions based on role
            } else {
                console.error("Login response does not include user role.");
                alert("Login failed. User role is missing.");
            }
        } catch (error) {
            console.error("Error during login:", error.message);
            alert(error.message);
        }
    };

    const authenticateUser = async (username, password) => {
        // Replace with your actual database query and logic
        const user = await User.findOne({ username });
    
        if (user && user.password === password) { // Use a secure password hash comparison in production
            return user; // Return the user if authentication succeeds
        }
        return null; // Return null if authentication fails
    };
    
    
    return (
        <Grid
            container
            alignItems="center"
            justifyContent="center"
            style={{ minHeight: '100vh', backgroundColor: '#f5f5f5' }}
        >
            <Grid item xs={11} sm={8} md={4}>
                <Card elevation={6} style={{ borderRadius: '12px' }}>
                    <CardContent>
                        <Box textAlign="center" mb={3}>
                            <Typography variant="h4" component="h1" gutterBottom>
                                Login
                            </Typography>
                            <Typography variant="body1" color="textSecondary">
                                Please enter your credentials to access the application.
                            </Typography>
                        </Box>

                        {errorMessage && (
                            <Typography variant="body2" color="error" align="center" gutterBottom>
                                {errorMessage}
                            </Typography>
                        )}

                        <form onSubmit={handleSubmit}>
                            <TextField
                                label="Username"
                                value={username}
                                onChange={(e) => setUsername(e.target.value)}
                                fullWidth
                                margin="normal"
                                variant="outlined"
                            />
                            <TextField
                                label="Password"
                                type="password"
                                value={password}
                                onChange={(e) => setPassword(e.target.value)}
                                fullWidth
                                margin="normal"
                                variant="outlined"
                            />
                            <Box mt={3}>
                                <Button
                                    type="submit"
                                    variant="contained"
                                    color="primary"
                                    fullWidth
                                    size="large"
                                    style={{ textTransform: 'none' }}
                                >
                                    Login
                                </Button>
                            </Box>
                        </form>
                    </CardContent>
                </Card>
            </Grid>
        </Grid>
    );
};

export default Login;
